// Minihra: Vrbčany → kopec → státovka vlevo → KM Prona → spánek
(() => {
  const cv = document.getElementById('game');
  if (!cv) return;
  const c = cv.getContext('2d'), W = 960, H = 540, GY = 400, L = 4600, S = 3200;
  const $ = id => document.getElementById(id);
  const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
  const sm = (a, b, x) => { x = clamp((x - a) / (b - a), 0, 1); return x * x * (3 - 2 * x); };
  const mix = (a, b, t) => a.map((v, i) => Math.round(v + (b[i] - v) * t));
  const rgb = a => `rgb(${a[0]},${a[1]},${a[2]})`;
  const FONT = '"Archivo Black",sans-serif', BODY = 'Barlow,sans-serif';
  const SLEEP_IMG = "data:image/webp;base64,";
  const HEAD = [.729, .178]; // poloha hlavy řidiče na fotce (podíl šířky a výšky)
  const sleepImg = new Image(); let nightImg = null;
  sleepImg.onload = () => {
    const o = document.createElement('canvas'); o.width = sleepImg.width; o.height = sleepImg.height;
    const x = o.getContext('2d'); x.drawImage(sleepImg, 0, 0);
    x.globalCompositeOperation = 'source-atop'; x.fillStyle = 'rgba(10,16,60,.34)'; x.fillRect(0, 0, o.width, o.height);
    nightImg = o;
  };
  sleepImg.src = SLEEP_IMG;
  let st, skin = 'classic', fl = 1, camX = 0, camY = 70, last = 0, vis = true;
  const keys = { gas: 0, brake: 0, blink: 0 };
  const terr = x => st.phase === 'A' ? 230 * sm(1700, 3700, x) + 6 * Math.sin(x / 90) : 230 + 3 * Math.sin(x / 170);
  const gy = x => GY - terr(x) - camY;
  const dim = a => rgb(mix(a, [12, 16, 40], st.sleep * .8));
  new IntersectionObserver(e => vis = e[0].isIntersecting).observe(cv);

  function reset() {
    st = { phase: 'A', mode: 'idle', x: 0, v: 0, fuel: 6, time: 0, t: 0, blink: 0, sleep: 0, fade: 0, smoke: [], wheel: 0, rust: false, tip: '', tipT: 0, sleepT: 0 };
    camY = 70;
  }
  function overlay(title, text, btn, win) {
    $('g-ov').classList.toggle('g-win', !!win);
    $('g-title').textContent = title; $('g-text').innerHTML = text; $('g-start').textContent = btn;
    $('g-ov').classList.remove('hide');
  }
  function end(title, text) { st.mode = 'over'; st.v = 0; overlay(title, text, 'Zkusit znovu'); }
  function turn() {
    st.phase = 'B'; st.x = 0; st.v *= .55; st.blink = 0; st.fade = 1;
    st.tip = 'Odbočeno na státovku. KM Prona je kus před tebou.'; st.tipT = 3.5;
  }

  /* ---------- logika ---------- */
  function update(dt) {
    st.t += dt;
    if (st.fade > 0) st.fade -= dt * 1.8;
    if (st.tipT > 0) st.tipT -= dt;
    if (st.mode === 'drive') {
      st.time += dt;
      const gas = keys.gas, slope = (terr(st.x + 20) - terr(st.x - 20)) / 40;
      if (st.fuel > 0) {
        st.fuel = Math.max(0, st.fuel - dt * gas * .22);
        if (st.fuel === 0) { st.rust = true; st.tip = 'Došla nafta! Oktávka jede na rez.'; st.tipT = 4; }
      }
      let a = gas * (st.fuel > 0 ? 200 : 105) - .55 * st.v - 18 - slope * 500 - keys.brake * 380;
      if (st.v <= 0 && a < 0) a = 0;
      st.v = Math.max(0, st.v + a * dt);
      st.x += st.v * dt; st.wheel += st.v * dt / 14;
      if (keys.blink) { st.blink = 2.5; keys.blink = 0; }
      if (st.blink > 0) st.blink -= dt;
      if ((gas || st.rust) && Math.random() < dt * (st.rust ? 12 : 22)) {
        st.smoke.push({ x: st.x - 82, h: terr(st.x - 82) + 22, vx: -22 - st.v * .12, vy: 14 + Math.random() * 10, r: 4, a: .5, col: st.rust ? '#9a4a22' : '#6b6f74' });
      }
      if (st.phase === 'A') {
        if (st.blink > 0 && st.x > L - 140 && st.x < L + 200) {
          if (st.v < 270) turn(); else { st.tip = 'Moc rychle! Zabrzdi a zkus to znovu.'; st.tipT = 2; }
        }
        if (st.x > L + 230) end('Vjel jsi do křoví', 'Státovku jsi minul. Příště zapni blinkr dřív a odboč vlevo.');
      } else {
        if (st.x > S - 110 && st.x < S + 110 && st.v < 12) { st.mode = 'sleep'; st.v = 0; st.tipT = 0; }
        else if (st.x > S + 280) end('Minul jsi benzinku', 'Za KM Pronou už je jen pole a rez. Zkus to znovu.');
      }
    } else if (st.mode === 'sleep') {
      st.sleep = Math.min(1, st.sleep + dt / 3.5); st.sleepT += dt;
      if (st.sleepT > 6 && !st.done) {
        st.done = 1;
        const jokes = ['Kotlik chrápe jako kotel v únoru.', 'Ráno ho čeká výměna sifonu a rozvaděč.', 'Oktávka tiká, chladne a drží pohromadě jen z cti.', 'Po probuzení objedná Wolt sám sobě.'];
        overlay('Kotlik se vyspal', `Cesta z Vrbčan: ${st.time.toFixed(0)} s. ${st.rust ? 'Dojel jsi na rez.' : 'Dojel jsi na poslední kapky nafty.'}<br>${jokes[Math.floor(Math.random() * jokes.length)]}`, 'Jet znovu', true);
      }
    }
    for (const p of st.smoke) { p.x += p.vx * dt; p.h += p.vy * dt * (p.col === '#9a4a22' ? -1 : 1); p.r += dt * 12; p.a -= dt * .7; }
    st.smoke = st.smoke.filter(p => p.a > 0);
    camX = st.x - 300;
    camY += (GY - terr(st.x) - 330 - camY) * Math.min(1, dt * 3);
  }

  /* ---------- kresba ---------- */
  function txt(s, x, y, font, col, al = 'center') {
    c.save(); c.translate(x, y); c.scale(fl, 1); c.font = font; c.fillStyle = col; c.textAlign = al; c.fillText(s, 0, 0); c.restore();
  }
  function hills(par, base, amp, col) {
    c.fillStyle = col; c.beginPath(); c.moveTo(0, H);
    for (let X = 0; X <= W + 20; X += 20) {
      const x = X + camX * par;
      c.lineTo(X, base - (camY - 70) * par * .5 - amp * (Math.sin(x * .004 + 1) + .6 * Math.sin(x * .011 + 2)));
    }
    c.lineTo(W, H); c.fill();
  }
  function curve(off) { c.beginPath(); for (let X = -20; X <= W + 20; X += 10) { const y = gy(X + camX) + off; X === -20 ? c.moveTo(X, y) : c.lineTo(X, y); } }
  function tree(x, s = 1) {
    const X = x - camX, Y = gy(x); if (X < -80 || X > W + 80) return;
    c.fillStyle = dim([92, 64, 40]); c.fillRect(X - 3 * s, Y - 30 * s, 6 * s, 30 * s);
    c.fillStyle = dim([54, 126, 62]);
    for (const [a, b, r] of [[0, -48, 20], [-13, -34, 15], [13, -34, 15]]) { c.beginPath(); c.arc(X + a * s, Y + b * s, r * s, 0, 7); c.fill(); }
  }
  function house(x, w, h, wall, roof) {
    const X = x - camX, Y = gy(x); if (X < -200 || X > W + 60) return;
    c.fillStyle = dim(wall); c.fillRect(X, Y - h, w, h);
    c.fillStyle = dim(roof); c.beginPath(); c.moveTo(X - 8, Y - h); c.lineTo(X + w / 2, Y - h - 36); c.lineTo(X + w + 8, Y - h); c.fill();
    c.fillStyle = dim([110, 74, 50]); c.fillRect(X + w * .42, Y - 34, 16, 34);
    c.fillStyle = dim([150, 200, 226]); c.fillRect(X + 10, Y - h + 16, 22, 20); c.fillRect(X + w - 32, Y - h + 16, 22, 20);
  }
  function church(x) {
    const X = x - camX, Y = gy(x); if (X < -200 || X > W + 100) return;
    c.fillStyle = dim([244, 236, 220]); c.fillRect(X, Y - 70, 90, 70); c.fillRect(X + 90, Y - 140, 34, 140);
    c.fillStyle = dim([170, 60, 44]); c.beginPath(); c.moveTo(X - 6, Y - 70); c.lineTo(X + 45, Y - 104); c.lineTo(X + 96, Y - 70); c.fill();
    c.beginPath(); c.moveTo(X + 86, Y - 140); c.lineTo(X + 107, Y - 205); c.lineTo(X + 128, Y - 140); c.fill();
    c.fillStyle = dim([60, 70, 80]); c.fillRect(X + 106, Y - 222, 2, 20); c.fillRect(X + 100, Y - 214, 14, 2);
    c.fillRect(X + 102, Y - 120, 10, 26);
  }
  function sign(x, lines, w, bg, fg) {
    const X = x - camX, Y = gy(x); if (X < -150 || X > W + 150) return;
    c.fillStyle = dim([90, 90, 96]); c.fillRect(X - 2, Y - 74, 4, 74);
    c.fillStyle = bg; c.fillRect(X - w / 2, Y - 130, w, 56); c.strokeStyle = fg; c.lineWidth = 2; c.strokeRect(X - w / 2 + 3, Y - 127, w - 6, 50);
    lines.forEach((s, i) => txt(s, X, Y - 106 + i * 20, `700 ${i ? 14 : 17}px ${BODY}`, fg));
  }
  function pole(x) {
    const X = x - camX, Y = gy(x); if (X < -60 || X > W + 400) return;
    c.fillStyle = dim([70, 56, 44]); c.fillRect(X - 3, Y - 130, 6, 130); c.fillRect(X - 22, Y - 124, 44, 5);
    const Y2 = gy(x + 340); c.strokeStyle = dim([40, 40, 46]); c.lineWidth = 1.5;
    for (const o of [-20, 20]) { c.beginPath(); c.moveTo(X + o, Y - 124); c.quadraticCurveTo(X + 170 + o, Math.max(Y, Y2) - 100, X + 340 + o, Y2 - 124); c.stroke(); }
  }
  function station() {
    const X = S - camX, Y = gy(S); if (X < -500 || X > W + 500) return;
    c.fillStyle = dim([233, 237, 242]); c.fillRect(X + 200, Y - 100, 200, 100);
    c.fillStyle = dim([201, 210, 220]); c.fillRect(X + 190, Y - 112, 220, 14);
    c.fillStyle = dim([143, 183, 214]); c.fillRect(X + 215, Y - 80, 70, 48); c.fillRect(X + 305, Y - 80, 70, 48);
    c.fillStyle = dim([215, 220, 226]); c.fillRect(X - 150, Y - 118, 10, 118); c.fillRect(X + 140, Y - 118, 10, 118);
    c.fillStyle = dim([28, 63, 134]); c.fillRect(X - 190, Y - 148, 380, 30);
    c.fillStyle = dim([245, 130, 32]); c.fillRect(X - 190, Y - 122, 380, 6);
    txt('KM PRONA', X, Y - 126, `18px ${FONT}`, '#fff');
    for (const px of [-70, 50]) {
      c.fillStyle = dim([226, 59, 46]); c.fillRect(X + px, Y - 62, 22, 62);
      c.fillStyle = dim([207, 233, 245]); c.fillRect(X + px + 4, Y - 54, 14, 14);
    }
    c.fillStyle = 'rgba(110,240,150,.38)'; c.fillRect(X - 110, Y + 2, 220, 10);
    c.fillStyle = '#fff'; c.fillRect(X - 112, Y + 2, 3, 10); c.fillRect(X + 109, Y + 2, 3, 10);
  }
  function pylon() {
    const X = S - 560 - camX, Y = gy(S - 560); if (X < -150 || X > W + 150) return;
    c.fillStyle = dim([215, 220, 226]); c.fillRect(X - 4, Y - 200, 8, 200);
    c.fillStyle = dim([28, 63, 134]); c.fillRect(X - 62, Y - 240, 124, 64);
    c.fillStyle = dim([245, 130, 32]); c.fillRect(X - 62, Y - 182, 124, 6);
    txt('KM PRONA', X, Y - 216, `16px ${FONT}`, '#fff'); txt('Nafta 36,90', X, Y - 194, `700 14px ${BODY}`, '#ffd21f');
  }
  function billboard(x) {
    const X = x - camX, Y = gy(x); if (X < -250 || X > W + 250) return;
    c.fillStyle = dim([90, 80, 70]); c.fillRect(X - 70, Y - 110, 6, 110); c.fillRect(X + 64, Y - 110, 6, 110);
    c.fillStyle = dim([255, 210, 31]); c.fillRect(X - 100, Y - 190, 200, 86);
    txt('KOTLIK', X, Y - 150, `30px ${FONT}`, '#0e3b43'); txt('kotle • záchody • elektro', X, Y - 122, `700 14px ${BODY}`, '#0e3b43');
  }

  function car() {
    const x = st.x, y = gy(x), ang = Math.atan2(-(terr(x + 24) - terr(x - 24)), 48);
    const moving = st.mode === 'drive' && st.v > 2, bounce = moving ? Math.abs(Math.sin(st.wheel * .9)) * (st.rust ? 2.2 : 1) : 0;
    const wolt = skin === 'wolt', cl = wolt ? ['#3fc3f2', '#0f8fc8'] : ['#d6dbdf', '#9aa2a9'];
    const fade = st.mode === 'sleep' ? clamp((st.sleep - .3) / .4, 0, 1) : 0;
    if (fade >= 1) return;
    c.globalAlpha = 1 - fade;
    c.save(); c.translate(x - camX, y - bounce); c.rotate(ang);
    c.fillStyle = 'rgba(0,0,0,.25)'; c.beginPath(); c.ellipse(0, 2 + bounce, 88, 6, 0, 0, 7); c.fill();
    c.strokeStyle = '#333'; c.lineWidth = 2; c.beginPath(); c.moveTo(-60, -66); c.lineTo(-18, -66); c.moveTo(-50, -70); c.lineTo(-50, -64); c.moveTo(-28, -70); c.lineTo(-28, -64); c.stroke();
    const g = c.createLinearGradient(0, -70, 0, -16); g.addColorStop(0, cl[0]); g.addColorStop(1, cl[1]);
    c.fillStyle = g; c.beginPath();
    c.moveTo(-78, -18); c.lineTo(-78, -40); c.quadraticCurveTo(-77, -44, -70, -44); c.lineTo(-62, -44); c.lineTo(-56, -68);
    c.lineTo(14, -68); c.lineTo(40, -44); c.lineTo(70, -40); c.quadraticCurveTo(80, -38, 80, -28); c.lineTo(80, -18); c.closePath(); c.fill();
    c.fillStyle = '#2a3640'; c.beginPath(); c.moveTo(-55, -46); c.lineTo(-51, -64); c.lineTo(10, -64); c.lineTo(32, -46); c.closePath(); c.fill();
    c.fillStyle = 'rgba(255,255,255,.14)'; c.beginPath(); c.moveTo(-40, -46); c.lineTo(-36, -64); c.lineTo(-22, -64); c.lineTo(-26, -46); c.fill();
    c.fillStyle = cl[1]; c.fillRect(-22, -64, 4, 18);
    c.fillStyle = '#35393e'; c.fillRect(-80, -24, 160, 8);
    c.fillStyle = '#fff3b0'; c.fillRect(74, -36, 6, 6);
    c.fillStyle = keys.brake && st.mode === 'drive' ? '#ff3b2f' : '#b3241c'; c.fillRect(-79, -38, 4, 9);
    c.fillStyle = '#a4521f';
    for (const [a, b, r] of [[-70, -30, 3.5], [-63, -23, 3], [-75, -22, 2.5], [-58, -30, 2], [18, -24, 2.5], [52, -29, 3], [-30, -20, 2]]) { c.beginPath(); c.arc(a, b, r, 0, 7); c.fill(); }
    if (wolt) {
      txt('Wolt', -2, -30, `italic 800 14px ${BODY}`, '#fff');
      c.fillStyle = '#19a7e0'; c.fillRect(-34, -86, 60, 18); txt('Wolt', -4, -72, `italic 800 13px ${BODY}`, '#fff');
    }
    if (st.blink > 0 && Math.floor(st.t * 4) % 2 === 0) {
      c.fillStyle = '#ffa31a'; c.fillRect(76, -30, 5, 5); c.fillRect(-80, -32, 4, 5);
      c.fillStyle = 'rgba(255,163,26,.35)'; c.beginPath(); c.arc(78, -28, 12, 0, 7); c.fill(); c.beginPath(); c.arc(-80, -30, 12, 0, 7); c.fill();
    }
    for (const wx of [-48, 50]) {
      c.fillStyle = '#1b1d20'; c.beginPath(); c.arc(wx, -14, 17, 0, 7); c.fill();
      c.save(); c.translate(wx, -14); c.fillStyle = '#16181b'; c.beginPath(); c.arc(0, 0, 13, 0, 7); c.fill();
      c.rotate(st.wheel); c.fillStyle = '#c4c9ce'; c.beginPath(); c.arc(0, 0, 7, 0, 7); c.fill();
      c.strokeStyle = '#6a7076'; c.lineWidth = 2;
      for (let k = 0; k < 5; k++) { c.rotate(Math.PI * 2 / 5); c.beginPath(); c.moveTo(0, 0); c.lineTo(6, 0); c.stroke(); }
      c.restore();
    }
    c.restore(); c.globalAlpha = 1;
    if (st.mode === 'sleep' && st.sleep < .3) {
      for (let i = 0; i < 3; i++) {
        const t = (st.t * .5 + i / 3) % 1;
        c.globalAlpha = 1 - t; txt('Z', x - camX + 10 + t * 50, y - 80 - t * 80, `${14 + t * 26}px ${FONT}`, '#fff'); c.globalAlpha = 1;
      }
    }
  }

  function glow(x, y, r, col, a) {
    const g = c.createRadialGradient(x, y, 0, x, y, r); g.addColorStop(0, col.replace('A', a)); g.addColorStop(1, col.replace('A', 0));
    c.fillStyle = g; c.fillRect(x - r, y - r, r * 2, r * 2);
  }

  function draw() {
    const n = st.sleep, B = st.phase === 'B';
    const sky = c.createLinearGradient(0, 0, 0, H * .8);
    sky.addColorStop(0, rgb(mix([88, 168, 230], [10, 14, 48], n))); sky.addColorStop(1, rgb(mix([255, 222, 160], [44, 48, 104], n)));
    c.fillStyle = sky; c.fillRect(0, 0, W, H);
    if (n > 0) { c.fillStyle = `rgba(255,255,255,${n})`; for (let i = 0; i < 70; i++) c.fillRect((i * 163) % W, (i * 71) % 270, i % 3 ? 1.5 : 2.5, i % 3 ? 1.5 : 2.5); }
    c.globalAlpha = 1 - n; glow(770, 120, 130, 'rgba(255,230,150,A)', .8); c.fillStyle = '#fff2b8'; c.beginPath(); c.arc(770, 120, 38, 0, 7); c.fill();
    c.globalAlpha = n; c.fillStyle = '#f2efd6'; c.beginPath(); c.arc(770, 110, 28, 0, 7); c.fill(); c.globalAlpha = 1;

    c.save(); if (B) { c.translate(W, 0); c.scale(-1, 1); fl = -1; } else fl = 1;
    c.fillStyle = `rgba(255,255,255,${.8 * (1 - n * .85)})`;
    for (const [cx, cy, s] of [[200, 90, 1], [700, 60, 1.2], [1300, 120, .9], [1900, 70, 1.1]]) {
      const X = ((cx - camX * .12) % 2400 + 2400) % 2400 - 300;
      for (const [a, b, r] of [[0, 0, 28], [30, 8, 22], [-30, 10, 20], [8, 14, 24]]) { c.beginPath(); c.ellipse(X + a * s, cy + b, r * s * 1.4, r * s * .8, 0, 0, 7); c.fill(); }
    }
    hills(.15, 300, 34, dim([140, 176, 200])); hills(.35, 340, 30, dim([98, 150, 104]));

    c.fillStyle = dim(B ? [154, 182, 80] : [104, 172, 76]); curve(0); c.lineTo(W + 20, H + 300); c.lineTo(-20, H + 300); c.fill();
    c.strokeStyle = 'rgba(0,0,0,.07)'; c.lineWidth = 6; for (let k = 1; k < 6; k++) { curve(30 + k * 26); c.stroke(); }

    if (!B) {
      for (let x = 60; x < L + 200; x += 210 + (x * 7 % 60)) tree(x, .9 + (x % 5) * .08);
      for (let i = 0; i < 10; i++) house(320 + i * 185, 90 + (i * 37 % 40), 62 + (i * 53 % 30), [[244, 226, 192], [233, 201, 160], [217, 228, 208], [241, 211, 211]][i % 4], [[181, 71, 47], [142, 58, 42], [108, 74, 58]][i % 3]);
      church(2150);
      sign(140, ['VRBČANY'], 120, '#fff', '#111');
      sign(L - 380, ['KM PRONA', '← státovka'], 150, '#1b4fa3', '#fff');
      for (let k = 0; k < 7; k++) { const X = L + 250 + k * 26 - camX, Y = gy(L + 250); c.fillStyle = dim([46 + k * 4, 110, 54]); c.beginPath(); c.arc(X, Y - 26 - (k % 2) * 12, 34, 0, 7); c.fill(); }
    } else {
      for (let x = 200; x < S + 900; x += 520) tree(x, 1.1);
      for (let x = 0; x < S + 900; x += 340) pole(x);
      billboard(1500); pylon(); station();
    }

    c.lineJoin = 'round'; curve(14); c.strokeStyle = '#3b4047'; c.lineWidth = 30; c.stroke();
    c.setLineDash([26, 22]); c.lineDashOffset = camX; curve(14); c.strokeStyle = '#eee'; c.lineWidth = 3; c.stroke(); c.setLineDash([]);
    curve(1); c.strokeStyle = '#c8ccd0'; c.lineWidth = 3; c.stroke();

    for (const p of st.smoke) { c.globalAlpha = Math.max(0, p.a); c.fillStyle = p.col; c.beginPath(); c.arc(p.x - camX, GY - p.h - camY, p.r, 0, 7); c.fill(); }
    c.globalAlpha = 1;
    car();

    if (n > 0) {
      c.fillStyle = `rgba(4,8,40,${.5 * n})`; c.fillRect(0, 0, W, H);
      c.globalCompositeOperation = 'lighter';
      const X = S - camX, Y = gy(S);
      glow(X, Y - 100, 260, 'rgba(255,220,140,A)', .45 * n); glow(X + 300, Y - 56, 150, 'rgba(255,220,140,A)', .5 * n);
      glow(st.x - camX - 5, gy(st.x) - 56, 40, 'rgba(255,230,160,A)', .25 * n);
      c.globalCompositeOperation = 'source-over';
    }
    c.restore(); fl = 1;
    sleepScene();
    if (st.fade > 0) { c.fillStyle = `rgba(0,0,0,${st.fade})`; c.fillRect(0, 0, W, H); }
    hud(); hint();
  }

  function sleepScene() {
    const a = clamp((st.sleep - .3) / .4, 0, 1); if (a <= 0 || !nightImg) return;
    const w = Math.min(600, W * .64), h = w * nightImg.height / nightImg.width, bx = W / 2, by = H - 16, br = Math.sin(st.t * 1.6);
    c.save(); c.globalAlpha = a;
    c.fillStyle = 'rgba(0,0,0,.4)'; c.beginPath(); c.ellipse(bx, by, w * .48, 11, 0, 0, 7); c.fill();
    c.translate(bx, by); c.scale(1 + br * .004, 1 + br * .01); c.drawImage(nightImg, -w / 2, -h, w, h);
    c.restore();
    const hx = bx - w / 2 + w * HEAD[0] + 26, hy = by - h + h * HEAD[1] - 34, k = 1 + Math.floor((st.t * 1.3) % 6);
    c.save(); c.globalAlpha = a; c.textAlign = 'left'; c.lineWidth = 6; c.lineJoin = 'round'; c.strokeStyle = '#0e3b43'; c.fillStyle = '#fff';
    for (let i = 0; i < k; i++) {
      c.font = `${20 + i * 7}px ${FONT}`; const zx = hx + i * 30, zy = hy - i * 20 - br * 3;
      c.strokeText('Z', zx, zy); c.fillText('Z', zx, zy);
    }
    c.restore();
  }

  function panel(x, y, w, h) { c.fillStyle = 'rgba(14,59,67,.88)'; c.beginPath(); c.roundRect(x, y, w, h, 14); c.fill(); }
  function hud() {
    c.textAlign = 'left'; panel(14, 14, 236, 86);
    c.fillStyle = '#ffd21f'; c.font = `34px ${FONT}`; c.fillText(Math.round(st.v * .28), 30, 58);
    c.fillStyle = '#cfe0e3'; c.font = `600 14px ${BODY}`; c.fillText('km/h', 98, 58);
    c.fillText(st.fuel > 0 ? `Nafta ${st.fuel.toFixed(1)} %` : 'Nafta 0 %, jedeš na rez', 30, 80);
    c.fillStyle = 'rgba(255,255,255,.2)'; c.fillRect(30, 86, 204, 6);
    c.fillStyle = st.fuel > 0 ? '#9be37d' : '#d07a3e'; c.fillRect(30, 86, st.fuel > 0 ? 204 * st.fuel / 6 : 204, 6);
    const p = st.phase === 'A' ? st.x / L * .55 : .55 + Math.min(1, st.x / S) * .45, x0 = 330, wd = 300;
    panel(x0 - 24, 14, wd + 48, 56);
    c.strokeStyle = 'rgba(255,255,255,.3)'; c.lineWidth = 4; c.beginPath(); c.moveTo(x0, 34); c.lineTo(x0 + wd, 34); c.stroke();
    c.textAlign = 'center'; c.font = `600 12px ${BODY}`; c.fillStyle = '#cfe0e3';
    [['Vrbčany', 0], ['křižovatka', .55], ['KM Prona', 1]].forEach(([s, f]) => { c.beginPath(); c.arc(x0 + f * wd, 34, 5, 0, 7); c.fill(); c.fillText(s, x0 + f * wd, 58); });
    c.fillStyle = '#ffd21f'; c.beginPath(); c.arc(x0 + clamp(p, 0, 1) * wd, 34, 8, 0, 7); c.fill();
  }
  function hint() {
    let s = '';
    if (st.mode === 'drive') {
      if (st.tipT > 0) s = st.tip;
      else if (st.time < 5) s = 'Drž plyn (→ nebo D) a jeď z Vrbčan do kopce';
      else if (st.phase === 'A' && st.x > L - 1000 && st.blink <= 0) s = 'Křižovatka se blíží. Zpomal (←), zapni blinkr (↑ nebo mezerník) a odboč vlevo.';
      else if (st.phase === 'B' && st.x > S - 900) s = 'KM Prona před tebou. Zabrzdi (← nebo S) v zeleném poli.';
    }
    if (!s) return;
    c.font = `600 16px ${BODY}`; const w = c.measureText(s).width + 36;
    panel(W / 2 - w / 2, H - 58, w, 38); c.fillStyle = '#fff'; c.textAlign = 'center'; c.fillText(s, W / 2, H - 33);
  }

  /* ---------- ovládání ---------- */
  const map = { ArrowRight: 'gas', KeyD: 'gas', ArrowLeft: 'brake', KeyA: 'brake', KeyS: 'brake', ArrowDown: 'brake' };
  addEventListener('keydown', e => {
    if (st.mode !== 'drive') return;
    if (map[e.code]) { keys[map[e.code]] = 1; e.preventDefault(); }
    if (['ArrowUp', 'KeyW', 'Space'].includes(e.code)) { keys.blink = 1; e.preventDefault(); }
  });
  addEventListener('keyup', e => { if (map[e.code]) keys[map[e.code]] = 0; });
  document.querySelectorAll('.g-pad button').forEach(b => {
    const k = b.dataset.k;
    b.addEventListener('pointerdown', e => { e.preventDefault(); keys[k] = 1; });
    ['pointerup', 'pointerleave', 'pointercancel'].forEach(t => b.addEventListener(t, () => { if (k !== 'blink') keys[k] = 0; }));
  });
  document.querySelectorAll('.g-skins button').forEach(b => b.addEventListener('click', () => {
    skin = b.dataset.skin; document.querySelectorAll('.g-skins button').forEach(x => x.classList.toggle('on', x === b));
  }));
  $('g-start').addEventListener('click', () => {
    reset(); st.mode = 'drive'; $('g-ov').classList.add('hide'); $('g-start').blur();
  });

  function loop(ts) {
    const dt = clamp((ts - last) / 1000 || 0, 0, .05); last = ts;
    if (vis) { update(dt); draw(); }
    requestAnimationFrame(loop);
  }
  reset(); requestAnimationFrame(loop);
})();
